INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('37dda3f8-bdc5-4735-89c1-b50876061bbf', 'Црква „Св. Архангел Михаил“ - Охрид', 'cultural', 'church', 'Охрид', 'Охрид', 41.117222, 20.794722, 4.5, 0, 30, 'religious, cultural, historical', 'Свети Архангел Михаил — македонска православна црква, сместена во стариот дел на Охрид , во населбата Кошишта . Камен-темелникот е осветен и поставен во 1985 година, а била осветена на 19 септември 1988 година од страна на Митрополитот Дебарско-кичевски г.', 'црква „св. архангел михаил“ - охрид', 'church cultural historical religious', 'https://scontent.fskp2-1.fna.fbcdn.net/v/t39.30808-6/491590730_9550026888417940_417445571436031276_n.jpg?_nc_cat=108&ccb=1-7&_nc_sid=e06c5d&_nc_ohc=AqKFFd5haq8Q7kNvwFPFeyJ&_nc_oc=AdnfmlzAeWMTHb5Z2sGKNhd1iUpWw5ybvw8WPVkI8IwNcS_HcfQaf0d_tkJUqsovcJw&_nc_zt=23&_nc_ht=scontent.fskp2-1.fna&_nc_gid=eX9Sf8blxuv-k9ytt6Fd9w&oh=00_Aftixjtx_emnY3fx6N29X3lw8yWwv0Db1lqfwTZ9dCFSXA&oe=69A55777') ON CONFLICT (place_id) DO NOTHING;
INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('6eaa0eb6-94db-4dfc-909f-fc79c59704e7', 'Црква „Св. Стефан“ - Шипокно', 'cultural', 'church', 'Шипокно', 'Охрид', 41.073861, 20.804278, 4.5, 0, 30, 'religious, cultural, historical', 'Свети Стефан , попозната како Свети Стефан Панцир — македонска пештерна црква , која се наоѓа во охридското село Шипокно , веднаш над населбата Свети Стефан . Црквата претставува главна манастирска црква на Шипокничкиот манастир .', 'црква „св. стефан“ - шипокно', 'church cultural historical religious', 'https://upload.wikimedia.org/wikipedia/commons/e/ea/%D0%A6%D1%80%D0%BA%D0%B2%D0%B0_%E2%80%9E%D0%A1%D0%B2._%D0%A1%D1%82%D0%B5%D1%84%D0%B0%D0%BD%E2%80%9C_-_%D0%A8%D0%B8%D0%BF%D0%BE%D0%BA%D0%BD%D0%BE_2.jpg') ON CONFLICT (place_id) DO NOTHING;
INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('fd8360d8-1cc3-407e-ac07-c32b36dddbe2', 'Црква „Пресвета Богородица Перивлепта“ - Охрид', 'cultural', 'church', 'Охрид', 'Охрид', 41.1142, 20.795444, 4.5, 0, 30, 'religious, cultural, historical', 'Пресвета Богородица Перивлепта ( Пресвета Богородица Севидна ) — црква наоѓа во градот Охрид , изградена пред 1295 година. Фресконатписот во нартексот , покрај други личности, ги споменува Прогон Згур и годината на „подигањето“, односно живописот на црквата, 1295 .', 'црква „пресвета богородица перивлепта“ - охрид', 'church cultural historical religious', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d8/%D0%A6%D1%80%D0%BA%D0%B2%D0%B0%D1%82%D0%B0_%D0%A1%D0%B2._%D0%91%D0%BE%D0%B3%D0%BE%D1%80%D0%BE%D0%B4%D0%B8%D1%86%D0%B0_%D0%9F%D0%B5%D1%80%D0%B8%D0%B2%D0%BB%D0%B5%D0%BF%D1%82%D0%B0%2C_%D0%9E%D1%85%D1%80%D0%B8%D0%B4.jpg/1280px-%D0%A6%D1%80%D0%BA%D0%B2%D0%B0%D1%82%D0%B0_%D0%A1%D0%B2._%D0%91%D0%BE%D0%B3%D0%BE%D1%80%D0%BE%D0%B4%D0%B8%D1%86%D0%B0_%D0%9F%D0%B5%D1%80%D0%B8%D0%B2%D0%BB%D0%B5%D0%BF%D1%82%D0%B0%2C_%D0%9E%D1%85%D1%80%D0%B8%D0%B4.jpg') ON CONFLICT (place_id) DO NOTHING;
INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('d9672178-a696-489c-bccf-78bcaa75b146', 'Црква „Успение на Пресвета Богородица“ - Охрид', 'cultural', 'church', 'Охрид', 'Охрид', 41.116222, 20.799246, 4.5, 0, 30, 'religious, cultural, historical', 'Успение на Пресвета Богородица (позната како: Света Богородица Каменско ) — македонски православен храм во градот Охрид . Оваа црква се наоѓа во строгиот центар на градот Охрид, во стариот дел на градот, над стариот чинар и фонтаната во чаршијата.', 'црква „успение на пресвета богородица“ - охрид', 'church cultural historical religious', 'https://scontent.fskp2-1.fna.fbcdn.net/v/t39.30808-6/241100302_1465936313799445_1990371837627168866_n.jpg?_nc_cat=100&ccb=1-7&_nc_sid=7b2446&_nc_ohc=ZtIKdSBfD20Q7kNvwGX_B6q&_nc_oc=AdlfXbQ4dnoLQ8T163InkAXndTwTy7_mVA18Gdx_eLpm5doVJZRj_B3oHC6sLzuBbuY&_nc_zt=23&_nc_ht=scontent.fskp2-1.fna&_nc_gid=7QupMMBnrweT2gi90hXVuw&oh=00_Afvr9JeGYFtbwsqdaqgz4Z5F5ug_7k39jkEyDsMcbUwSeg&oe=69A55D2E') ON CONFLICT (place_id) DO NOTHING;
INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('f9b6cc65-4679-41e8-926f-8d75bb8c1840', 'Црква „Св. Богородица“ - Заум', 'cultural', 'church', 'Трпејца', 'Охрид', 40.948963, 20.774746, 4.5, 0, 30, 'religious, cultural, historical', '„Св. Богородица Захумска“ или само Заум — средновековна црква која се наоѓа веднаш на самиот источниот брег од Охридското Езеро , во непосредна близина на селото Трпејца .', 'црква „св. богородица“ - заум', 'church cultural historical religious', 'https://galicica.org.mk/wp-content/uploads/2019/07/crkva-sv-bogorodica-zahumska-18.jpg') ON CONFLICT (place_id) DO NOTHING;
INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('21973b8b-a1dd-4b07-9613-b537dc0ab31b', 'Црква „Воведение на Пресвета Богородица“ - Охрид', 'cultural', 'church', 'Охрид', 'Охрид', 41.090628, 20.809083, 4.5, 0, 30, 'religious, cultural, historical', 'Воведение на Пресвета Богородица во Храм — пештерна црква во Охридската населба Канео и се наоѓа јужно од главниот храм посветен на Св. Јован Богослов - Канео .', 'црква „воведение на пресвета богородица“ - охрид', 'church cultural historical religious', 'https://tvm.mk/wp-content/themes/yootheme/cache/33/444467505_825007263022399_6432773644893784853_n-33d63c26.jpeg?x34247') ON CONFLICT (place_id) DO NOTHING;
INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('cfb638d0-f749-4455-99ff-6b8a8a9e3a0e', 'Црква „Рождество на Пресвета Богородица“ - Охрид', 'cultural', 'church', 'Охрид', 'Охрид', 41.110949, 20.788888, 4.5, 0, 30, 'religious, cultural, historical', 'Црквата Рождество на Пресвета Богородица — црква на Првата охридска парохија во Охридското архијерејско намесништво во Дебарско-кичевската епархија на Македонската православна црква . Оваа црква се наоѓа во населбата Канео и е сместена во карпа под црквата „Св. Јован Канео“.', 'црква „рождество на пресвета богородица“ - охрид', 'church cultural historical religious', 'https://upload.wikimedia.org/wikipedia/commons/1/19/Sv._Bogorodica_pod_Kaneo.JPG') ON CONFLICT (place_id) DO NOTHING;
