INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('2b4f922e-9c9e-4ff9-b56f-237d455f705a', 'Црква „Св. Ѓорѓи“ - Охрид', 'cultural', 'church', 'Охрид', 'Охрид', 41.117582, 20.813523, 4.5, 0, 30, 'religious, cultural, historical', 'Свети Ѓорѓија — македонски православен храм во градот Охрид . Поточно, црквата се наоѓа во источниот (горниот) дел на градот, на крајот на населбите Расадник и Горна Влашка Маала, во близината на Градската општа болница и кружниот тек на патот кој води кон селото Велгошти и во правец на Битола .', 'црква „св. ѓорѓи“ - охрид', 'church cultural historical religious', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/%D0%A6%D1%80%D0%BA%D0%B2%D0%B0_%D0%A1%D0%B2._%D0%83%D0%BE%D1%80%D1%93%D0%B8%2C_%D0%9E%D1%85%D1%80%D0%B8%D0%B4.jpg/1280px-%D0%A6%D1%80%D0%BA%D0%B2%D0%B0_%D0%A1%D0%B2._%D0%83%D0%BE%D1%80%D1%93%D0%B8%2C_%D0%9E%D1%85%D1%80%D0%B8%D0%B4.jpg?_=20141031171218') ON CONFLICT (place_id) DO NOTHING;
INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('f220df6a-5bee-4828-9a75-e58ecaf3c2d0', 'Црква „Св. Екатерина“ - Охрид', 'cultural', 'church', 'Охрид', 'Охрид', 41.144122, 20.761376, 4.5, 0, 30, 'religious, cultural, historical', 'Света Екатерина — пештерна црква во близина на брегот на Охридското Езеро , веднаш лево од патот што води кон Охрид. Се наоѓа во близина на попознатата пештерна црква „Св. Еразмо“', 'црква „св. екатерина“ - охрид', 'church cultural historical religious', 'https://upload.wikimedia.org/wikipedia/commons/e/ee/%D0%9C%D0%B0%D1%87%D0%B5%D0%BD%D0%B8%D1%86%D0%B0_%D0%95%D0%9A%D0%90%D0%A2%D0%95%D0%A0%D0%98%D0%9D%D0%90.jpg') ON CONFLICT (place_id) DO NOTHING;
INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('23c642d1-ac7e-4740-afd3-b61143679662', 'Црква „Св. Еразмо“ - Охрид', 'cultural', 'church', 'Охрид', 'Охрид', 41.142188, 20.761461, 4.5, 0, 30, 'religious, cultural, historical', 'Свети Еразмо — пештерна црква во близина на Охрид , Македонија . Оваа црква, посветена на антиохискиот архиепископ Еразмо се наоѓа на околу три километри од Охрид , во карпите, десно од патот што води од Охрид кон Струга .', 'црква „св. еразмо“ - охрид', 'church cultural historical religious', 'https://upload.wikimedia.org/wikipedia/commons/2/25/Sv._Erazmo_Peshterski-Ohrid_06.JPG') ON CONFLICT (place_id) DO NOTHING;
