INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('5720b872-e1fe-49c2-8b1f-e1b0ba43fd1f', 'Црква „Св. Богородица Челница“ - Охрид', 'cultural', 'church', 'Охрид', 'Охрид', 41.113333, 20.797222, 4.5, 0, 30, 'religious, cultural, historical', 'Света Богородица Челничка — македонска православна црква, сместена во стариот дел на Охрид , во населбата Варош . Црквата се наоѓа југоисточно од црквата „Мали Св.', 'црква „св. богородица челница“ - охрид', 'church cultural historical religious', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/%D0%A1%D0%B2._%D0%91%D0%BE%D0%B3%D0%BE%D1%80%D0%BE%D0%B4%D0%B8%D1%86%D0%B0_%D0%A7%D0%B5%D0%BB%D0%BD%D0%B8%D1%86%D0%B0_03.JPG/1280px-%D0%A1%D0%B2._%D0%91%D0%BE%D0%B3%D0%BE%D1%80%D0%BE%D0%B4%D0%B8%D1%86%D0%B0_%D0%A7%D0%B5%D0%BB%D0%BD%D0%B8%D1%86%D0%B0_03.JPG') ON CONFLICT (place_id) DO NOTHING;
INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('7fcfe461-f932-4653-aedc-a9c413870598', 'Црква „Вознесение Христово“ - Трпејца', 'cultural', 'church', 'Трпејца', 'Охрид', 40.988611, 20.814056, 4.5, 0, 30, 'religious, cultural, historical', 'Вознесение Христово — нова црква во охридското село Трпејца , Македонија .', 'црква „вознесение христово“ - трпејца', 'church cultural historical religious', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/%D0%A6%D1%80%D0%BA%D0%B2%D0%B0_%E2%80%9E%D0%A1%D0%B2._%D0%A1%D0%BF%D0%B0%D1%81%E2%80%9C_-_%D0%A2%D1%80%D0%BF%D0%B5%D1%98%D1%86%D0%B0.jpg/960px-%D0%A6%D1%80%D0%BA%D0%B2%D0%B0_%E2%80%9E%D0%A1%D0%B2._%D0%A1%D0%BF%D0%B0%D1%81%E2%80%9C_-_%D0%A2%D1%80%D0%BF%D0%B5%D1%98%D1%86%D0%B0.jpg') ON CONFLICT (place_id) DO NOTHING;
INSERT INTO places ("place_id", "name", "category", "type", "place", "municipality", "lat", "lng", "rating", "price", "time_to_visit", "tags", "description", "name_normalized", "model_text", "image_url") VALUES ('ea508bf4-e247-4a70-acbc-206204f784d2', 'Црква „Св. Влмч Димитриј“ - Охрид', 'cultural', 'church', 'Охрид', 'Охрид', 41.112806, 20.799833, 4.5, 0, 30, 'religious, cultural, historical', 'Свети Димитриј - православна црква на охридскиот плоштад, една од двете кои го носат името на Свети Димитриј во градот. Темелите на објектот укажуваат дека се работи за стара ранохристијанска црква која била изградена во VI век , и постоела до доаѓањето на Турците, кои во XIII – XIV ја срушиле и врз темелите изградиле џамија, која постоела до 1947 година, која за време на турското владеење била претворена во џамија.', 'црква „св. влмч димитриј“ - охрид', 'church cultural historical religious', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Sv._Dimitrija_Velikoma%C4%8Denik_Ohridski_plo%C5%A1tad.JPG/1280px-Sv._Dimitrija_Velikoma%C4%8Denik_Ohridski_plo%C5%A1tad.JPG') ON CONFLICT (place_id) DO NOTHING;
